<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title data-i18n="Reset password — Crea-Biz">Reset password — Crea-Biz</title><script src="/theme.js"></script><link rel="stylesheet" href="/platform.css"><script src="/locale-data.js" defer></script><script src="/locale.js" defer></script></head><body><main><h1><span data-i18n="Reset password">Reset password</span></h1><form id="reset-password"><input type="hidden" name="token" value="{{ $token }}"><label><span data-i18n="Email">Email</span><input name="email" type="email" value="{{ request('email') }}" autocomplete="email" required></label><label><span data-i18n="New password">New password</span><input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label><span data-i18n="Confirm password">Confirm password</span><input name="password_confirmation" type="password" autocomplete="new-password" required></label><button><span data-i18n="Reset password">Reset password</span></button></form><p id="status" role="status"></p><a href="/"><span data-i18n="Return to sign in">Return to sign in</span></a></main><script src="/account.js" defer></script></body></html>